function Invoke-ProFilemanagerPhase($Session,[string]$Phase,$Guard,[string]$ProNonce){
 $meta=$Guard.ReadCommand('filemanager-inputs.json')|ConvertFrom-Json
 if($meta.format -ne 1 -or $meta.proNonce -ne $ProNonce -or $meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.supportCase -notmatch '^[a-f0-9]{32}$' -or $meta.zipSha256 -notmatch '^[a-f0-9]{64}$'){throw 'Bound filemanager fixture required'}
 if($Phase -eq 'filemanager-step'){
  $requestInput=$Guard.ReadCommand('filemanager-command-inputs.json')|ConvertFrom-Json
  return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$requestInput -ScriptBlock {
   param($caseId,$requestInput)
   function Read-SharedGuiJson([string]$file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{$reader=[IO.StreamReader]::new($stream,[Text.Encoding]::UTF8);return $reader.ReadToEnd()|ConvertFrom-Json}finally{$stream.Dispose()}}
   $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\filemanager-'+$caseId;$approved='C:\MuLab\approved\filemanager-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$owner=Read-SharedGuiJson ($prefix+'-owner.json');$progress=Read-SharedGuiJson ($prefix+'-progress.json');$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
   if($requestInput.caseId -ne $caseId -or $requestInput.requestId -notmatch '^[a-f0-9-]{36}$' -or $requestInput.action -notin @('capture','click','key','type','verify','finish') -or -not $progress.ready -or $progress.pid -ne $owner.pid -or $progress.nonce -cne $owner.nonce -or (Test-Path ($prefix+'-result.json')) -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*pro-filemanager-client.mjs*'+$caseId+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Exact live synthetic GUI owner required'}
   $file=$approved+'-command.json';if(Test-Path $file){$old=[IO.File]::ReadAllText($file)|ConvertFrom-Json;if($old.sequence -gt $progress.sequence){throw 'Previous GUI step is still pending'}}
   $request=@{caseId=$caseId;ownerPid=$owner.pid;nonce=$owner.nonce;sequence=([int]$progress.sequence+1);requestId=$requestInput.requestId;action=$requestInput.action}
   if($requestInput.action -eq 'click'){if($requestInput.x -lt 0 -or $requestInput.x -gt 1 -or $requestInput.y -lt 0 -or $requestInput.y -gt 1){throw 'Viewer point outside bounded canvas'};$request.x=[double]$requestInput.x;$request.y=[double]$requestInput.y}
   if($requestInput.action -eq 'key'){if($requestInput.key -notin @('Control+2','Control+l','Control+a','Control+x','Control+v','Home','ArrowDown','F2','Enter','Escape','Delete')){throw 'Unsupported GUI key'};$request.key=$requestInput.key}
   if($requestInput.action -eq 'type'){switch($requestInput.text){'renamed'{$request.text='renamed-'+$caseId+'.txt'};'folder'{$request.text='/home/dev/Downloads/fm-'+$caseId};'target'{$request.text='/home/dev/Downloads/fm-'+$caseId+'/target'};default{throw 'Only fixed synthetic names may be typed'}}}
   $handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$next=$file+'.'+[guid]::NewGuid().ToString('N')+'.next';[IO.File]::WriteAllText($next,($request|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));if(Test-Path $file){[IO.File]::Replace($next,$file,[NullString]::Value)}else{[IO.File]::Move($next,$file)};$until=[DateTime]::UtcNow.AddSeconds(40)
   do{if(Test-Path ($prefix+'-result.json')){throw 'GUI validation ended; inspect its terminal result'};$observed=Read-SharedGuiJson ($prefix+'-progress.json');if($observed.pid -ne $owner.pid -or $observed.nonce -cne $owner.nonce){throw 'GUI progress owner changed'};if($observed.sequence -eq $request.sequence){return @{complete=$true;caseId=$caseId;acknowledged=$true;sequence=$request.sequence;requestId=$request.requestId;step=@($observed.steps)[-1]}};if($handle.HasExited -or [DateTime]::UtcNow -gt $until){throw 'GUI step unconfirmed; preserve process and inspect'};Start-Sleep -Milliseconds 100}while($true)
  }
 }
 if($Phase -in @('filemanager-stage','filemanager-stage-finish')){
  $Guard.PinInputFile([string]$meta.zip);if((Get-FileHash -LiteralPath $meta.zip).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Filemanager archive changed'}
  Invoke-Command -Session $Session -ScriptBlock {if((Get-Service vmms).Status -ne 'Running' -or @(Get-VM).Count){throw 'Ready empty Pro required'}}
  $archive='C:\MuLab\private\filemanager-'+$meta.caseId+'.zip';if($Phase -eq 'filemanager-stage'){Copy-Item -LiteralPath $meta.zip -Destination $archive -ToSession $Session}
  return Invoke-Command -Session $Session -ArgumentList $meta,$archive,($Phase -eq 'filemanager-stage-finish') -ScriptBlock {
   param($meta,$archive,$finish)
   $ErrorActionPreference='Stop';$tools='C:\MuLab\filemanager-tools\'+$meta.caseId
   if((Test-Path -LiteralPath $tools) -ne $finish){throw 'Filemanager staging state requires inspection'}
   $configFile='C:\MuLab\approved\filemanager-'+$meta.caseId+'-config.json';$emptyConfig=$false
   if(Test-Path $configFile){$entry=Get-Item -LiteralPath $configFile;if(-not $finish -or $entry.PSIsContainer -or $entry.Length -ne 0 -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Existing filemanager config requires inspection'};$emptyConfig=$true}
   if((Test-Path ('C:\MuLab\public\filemanager-'+$meta.caseId+'-owner.json')) -or (Get-ScheduledTask -TaskName ('MuPro-filemanager-'+$meta.caseId) -ErrorAction SilentlyContinue)){throw 'Only unused unfinished filemanager staging may finish'}
   foreach($folder in @('C:\','C:\MuLab','C:\MuLab\filemanager-tools')){if((Test-Path -LiteralPath $folder) -and ((Get-Item -LiteralPath $folder).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Filemanager staging reparse directory refused'}}
   $expected='C:\MuLab\image-tools\'+$meta.supportCase;$support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$node=Join-Path $expected 'product/resources/node/node.exe'
   if($support.caseId -ne $meta.supportCase -or $support.tools -ne $expected -or $support.image -ne ('C:\MuLab\images\image-'+$meta.supportCase+'.vhdx') -or $support.imageSha256 -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256 -or (Get-FileHash -LiteralPath (Join-Path $expected 'electron/electron.exe')).Hash.ToLowerInvariant() -ne $meta.electronSha256 -or (Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Filemanager base/runtime/archive changed'}
   Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive)
   try{[long]$bytes=0;if($zip.Entries.Count -gt 12000){throw 'Excessive filemanager entries'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$bytes+=$entry.Length;if($bytes -gt 2GB -or $entry.Length -gt 128MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('app/') -and $name -notin @('pro-filemanager-client.mjs','pro-filemanager-electron.cjs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe filemanager archive'}}}finally{$zip.Dispose()}
   if(-not $finish){[IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools)};if((Get-Item -LiteralPath $tools).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Filemanager tools reparse directory refused'};foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Filemanager fixture changed'}}
   foreach($entry in $meta.artifacts.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path (Join-Path $tools 'app') $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Filemanager program changed'}}
   $config=@{caseId=$meta.caseId;proNonce=$meta.proNonce;version=$meta.version;tools=$tools;app=(Join-Path $tools 'app');support=$expected;node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$support.imageSha256;files=$meta.files;artifacts=$meta.artifacts;sourceDigest=$meta.sourceDigest;electronSha256=$meta.electronSha256;userSid=(Get-LocalUser MuLabUser).SID.Value}
   if($emptyConfig){if((Get-Item -LiteralPath $configFile).Length -ne 0){throw 'Unfinished filemanager config changed'};[IO.File]::Move($configFile,($configFile+'.empty-'+[guid]::NewGuid().ToString('N')))}
   $file='C:\MuLab\approved\filemanager-'+$meta.caseId+'-config.json';$stream=[IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$configBytes=[Text.UTF8Encoding]::new($false).GetBytes(($config|ConvertTo-Json -Depth 8));$stream.Write($configBytes,0,$configBytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};return @{complete=$true;staged=$true;caseId=$meta.caseId;desktopBaseReused=$true}
  }
 }
 $response=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$Phase -ScriptBlock {
  param($caseId,$phase)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\filemanager-'+$caseId;$approved='C:\MuLab\approved\filemanager-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json
  if($cfg.caseId -ne $caseId -or $cfg.tools -ne ('C:\MuLab\filemanager-tools\'+$caseId)){throw 'Filemanager identity changed'}
  if($phase -eq 'filemanager-inspect'){
   $reports=@();foreach($kind in @('progress','result')){if(Test-Path ($prefix+'-'+$kind+'.json')){$reports+=[IO.File]::ReadAllText($prefix+'-'+$kind+'.json')|ConvertFrom-Json}}
   $logs=@();foreach($file in @(($prefix+'-client.log'),($approved+'-broker-error.log'))){if(Test-Path $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{if($stream.Length -gt 5000){$stream.Position=$stream.Length-5000};$reader=[IO.StreamReader]::new($stream);$logs+=@{name=[IO.Path]::GetFileName($file);tail=$reader.ReadToEnd()}}finally{$stream.Dispose()}}}
   $hashes=@{};foreach($entry in $cfg.artifacts.psobject.Properties){$hashes[$entry.Name]=(Get-FileHash (Join-Path $cfg.app $entry.Name)).Hash.ToLowerInvariant()};$dist=Join-Path $cfg.app 'dist';foreach($file in @(Get-ChildItem -LiteralPath $dist -File -Recurse)){$relative='dist/'+$file.FullName.Substring($dist.Length+1).Replace('\','/');$hashes[$relative]=(Get-FileHash -LiteralPath $file.FullName).Hash.ToLowerInvariant()};$diagnostics=@{};foreach($name in @('pro-filemanager-client.mjs','pro-filemanager-electron.cjs')){$diagnostics[$name]=(Get-FileHash (Join-Path $cfg.tools $name)).Hash.ToLowerInvariant()};$nested=@(Get-VM|ForEach-Object{@{id=[string]$_.Id;name=$_.Name;state=[string]$_.State}})
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json
   return @{complete=$true;caseId=$caseId;version=$cfg.version;reports=$reports;logs=$logs;artifactHashes=$hashes;diagnosticHashes=$diagnostics;clientSha256=(Get-FileHash (Join-Path $cfg.tools 'pro-filemanager-client.mjs')).Hash.ToLowerInvariant();actors=@(Get-CimInstance Win32_Process|Where-Object{(($_.ExecutablePath -eq $cfg.node -or $_.ExecutablePath -eq (Join-Path $cfg.support 'electron/electron.exe')) -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}|Select-Object ProcessId,ExecutablePath,CommandLine);nested=$nested;registeredGuests=@($ledger.records.psobject.Properties).Count;runtimeDirectories=@(Get-ChildItem -LiteralPath (Join-Path $root 'vms') -Force).Count;registrationCopiesEqual=((Get-FileHash (Join-Path $root 'vms.json')).Hash -eq (Get-FileHash (Join-Path $root 'vms.backup.json')).Hash);sourceDigest=$cfg.sourceDigest}
  }
  if($phase -ne 'filemanager-run' -or @(Get-VM).Count -or (Get-Service vmms).Status -ne 'Running'){throw 'Ready empty Pro required for filemanager run'}
  $task='MuPro-filemanager-'+$caseId;$ownerFile=$prefix+'-owner.json';$resultFile=$prefix+'-result.json';if((Test-Path $ownerFile) -or (Test-Path $resultFile) -or (Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue)){throw 'Existing filemanager work must be inspected'}
  $script=Join-Path $cfg.tools 'pro-filemanager-client.mjs';foreach($entry in $cfg.files.psobject.Properties){if((Get-FileHash (Join-Path $cfg.tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Filemanager inputs changed'}};if((Get-FileHash $cfg.node).Hash.ToLowerInvariant() -ne $cfg.nodeSha256){throw 'Filemanager Node changed'}
  $launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$cfg.node+''' --no-warnings '''+$script+''' '+$caseId+' *> '''+$prefix+'-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch));$principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1)) -MultipleInstances IgnoreNew;Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
  $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Filemanager owner not observed; retain task for inspection'};Start-Sleep -Milliseconds 200};$owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid);if($owner.caseId -ne $caseId -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*'+$script+'*'+$caseId+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Filemanager controller identity changed'}
  $handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $artifact.brokerFile;if($artifact.sourceDigest -ne $cfg.sourceDigest -or (Get-FileHash $broker).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Filemanager protected broker changed'}
  $agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ($approved+'-broker-out.log') -RedirectStandardError ($approved+'-broker-error.log') -PassThru;$null=$agent.Handle;$until=[DateTime]::UtcNow.AddMinutes(35)
  do{if(Test-Path $resultFile){if(-not $handle.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Filemanager controller or broker remains live'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Filemanager result identity changed'};$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName brokerExitConfirmed -NotePropertyValue $true;[IO.File]::WriteAllText($approved+'-result.json',($result|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result};if($handle.HasExited){throw 'Filemanager controller exited without receipt; retain resources'};if([DateTime]::UtcNow -gt $until){throw 'Filemanager run remains unconfirmed; inspect live handles'};Start-Sleep -Milliseconds 200}while($true)
 }
 if($Phase -eq 'filemanager-inspect'){$encoded=Invoke-Command -Session $Session -ArgumentList $meta.caseId -ScriptBlock {param($caseId) $cfg=[IO.File]::ReadAllText(('C:\MuLab\approved\filemanager-'+$caseId+'-config.json'))|ConvertFrom-Json;$file='C:\MuLab\public\filemanager-'+$caseId+'-ui.png';if(-not(Test-Path $file)){return $null};$info=Get-Item -LiteralPath $file;if($info.PSIsContainer -or $info.Length -gt 10MB -or $info.Length -lt 33 -or ($info.Attributes -band [IO.FileAttributes]::ReparsePoint) -or [IO.File]::GetAccessControl($file).GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $cfg.userSid){throw 'Synthetic viewer screenshot invalid'};$bytes=[IO.File]::ReadAllBytes($file);if([Convert]::ToBase64String($bytes[0..7]) -ne 'iVBORw0KGgo='){throw 'Viewer screenshot not PNG'};return [Convert]::ToBase64String($bytes)};if($encoded){$file=$Guard.Reserve('filemanager-ui-'+[guid]::NewGuid().ToString('N')+'.png');[IO.File]::WriteAllBytes($file,[Convert]::FromBase64String($encoded));$response.screenshot=$file}}
 return $response

}
